	val summary: String,
	val title: String,
	val failures: Long,
	val pending: Long,
	val thinking: List<HistoryThought>,
	val steps: List<HistoryStep>
)

/// What an item of the history is.
@OptIn(ExperimentalSerializationApi::class)
@JsonClassDiscriminator("kind")
@Serializable
sealed class HistoryBody {
	@Serializable
	@SerialName("received")
	data class Received(val content: HistoryReceived): HistoryBody()
	@Serializable
	@SerialName("text")
	data class Text(val content: HistoryText): HistoryBody()
	@Serializable
	@SerialName("post")
	data class Post(val content: HistoryPost): HistoryBody()
	@Serializable
	@SerialName("mark")
	data class Mark(val content: HistoryMark): HistoryBody()
	@Serializable
	@SerialName("group")
	data class Group(val content: HistoryGroup): HistoryBody()
}

/// One item of an execution history, and the transcript entries it draws (`entries`: first, last).
@Serializable
data class HistoryItem (
	val key: String,
	val entries: List<Long>,
	val body: HistoryBody
)

@Serializable
data class HistoryLive (
	val id: String,
	val text: String
)

/// A wait in an agent's history: from its mark (`since`) until the next word brought it back (`until`, absent while it
/// still waits: count on from `since`), at most `seconds`.
@Serializable
data class HistoryWait (
	val since: Long,
	val until: Long? = null,
	val seconds: Long? = null
)

/// A state the agent marked, in words; `wait` when it went to wait on work it started (drawn with an hourglass).
@Serializable
data class HistoryMark (
	val text: String,
	val wait: HistoryWait? = null
)

/// A place a message came from or went to: a chat on ember's page (`session`: the agent it opens), or a Slack thread.
@Serializable
data class Place (
	/// An ember chat's title, or a Slack thread's workspace and channel (`Cue#ops`).
	val name: String,
	/// ember | slack
	val surface: String,
	val session: String? = null,
	/// A Slack thread's link in Slack, while a connect is signed in to its workspace.
	val url: String? = null
)

@Serializable
data class HistoryMessage (
	val key: String,
	val from: HistoryFrom,
	val text: String,
	val place: Place? = null
)

@Serializable
data class HistoryPhase (
	val phase: String,
	val text: String,
	val since: Long
)

/// A message the agent posted: where to, whether it ended its work blocked, whether it failed.
@Serializable
data class HistoryPost (
	val text: String,
	val place: Place? = null,
	val block: Boolean,
	val failed: Boolean
)

/// What a prompt carried: ember's own words around them (`note`), then the messages.
@Serializable
data class HistoryReceived (
	val note: String? = null,
	val messages: List<HistoryMessage>
)

/// The agent's own words; `subagent`: a sub-agent's.
@Serializable
data class HistoryText (
	val text: String,
	val subagent: Boolean
)

@Serializable
data class UsageLine (
	val label: String,
	val value: String
)

/// An agent's execution history, read for people (history.rs).
@Serializable
data class HistoryView (
	val items: List<HistoryItem>,
	val live: List<HistoryLive>,
	val phase: HistoryPhase? = null,
	val usage: List<UsageLine>? = null,
	val usageLine: String? = null,
	/// What shows at its top: where the session begins, or why there is nothing (yet).
	val edge: String,
	val empty: Boolean,
	val loaded: Boolean,
	/// Older entries exist: `history.older` loads the page before them.
	val more: Boolean? = null
)

@Serializable
data class Memory (
	val totalBytes: Long,
	val usedBytes: Long,
	val swapUsedBytes: Long? = null
)

/// CPU, memory or disk: how full (and how bad: ok | amber | red), in words.
@Serializable
data class Meter (
	val label: String,
	val short: String,
	val percent: Long,
	val level: Level,
	val value: String,
	val note: String? = null
)

/// The machine a station runs on, with it in words.
@Serializable
data class Host (
	val hostname: String,
	val os: String,
	val arch: String,
	val cpus: Long,
	val cpuModel: String,
	val load: Double,
	val uptimeSec: Double,
	val memory: Memory,
	val disk: Disk,
	val emberRssBytes: Long,
	val checkedAt: Long,
	val summary: String,
	val line: String,
	val facts: List<String>,
	val meters: List<Meter>,
	val emberText: String
)

@Serializable
data class TimelineEntry (
	val at: String? = null,
	/// user | assistant | thinking | tool_call | tool_result
	val kind: String,
	val text: String,
	val tool: String? = null,
	val ok: Boolean? = null,
	val callId: String? = null,
	val subagent: Boolean? = null
)

@Serializable
data class TranscriptUsage (
	val modelCalls: Long,
	val inputTokens: Long,
	val cachedTokens: Long,
	val outputTokens: Long,
	val model: String? = null
)

/// A step in flight; an ended one stays until the transcript entry that records it arrives.
@Serializable
data class LiveStep (
	val id: String,
	/// text | thinking | tool
	val step: String,
	val tool: String? = null,
	val subagent: Boolean? = null,
	val parent: String? = null,
	val input: String,
	val startedAt: Long,
	val ended: Boolean? = null
)

/// Where the turn stands with the model (starting | requesting | responding | working), since when.
@Serializable
data class Phase (
	val phase: String,
	val since: Long
)

/// A session as it runs: its transcript (its latest entries once `loaded`, from entry `first`; `history.older` loads
/// those before), the model's use, the steps in flight, where the turn stands, how fast it writes, and its activity.
@Serializable
data class Live (
	val loaded: Boolean,
	val first: Long? = null,
	val timeline: List<TimelineEntry>,
	val usage: TranscriptUsage? = null,
	val steps: List<LiveStep>,
	val phase: Phase? = null,
	val rate: Long? = null,
	val activity: Activity? = null,
	/// Its station is offline: this is what was kept.
	val offline: Boolean? = null
)

/// Who the station machine's own Claude Code or Codex is signed in as (only read: ember never takes the login over).
@Serializable
data class MachineLogin (
	val runtime: RuntimeKind,
	val installed: Boolean,
	val loggedIn: Boolean,
	val email: String? = null,
	val plan: String? = null,
	/// A profile can use it as it is (kept in a file, not only in the keychain).
	val usable: Boolean? = null,
	/// Its allowance, as a profile on it would show (none until read, or when it cannot be).
	val quota: Quota? = null,
	/// In a line, as the pages show it.
	val text: String
)

@Serializable
data class SlackAppLinks (
	val settings: String,
	val install: String,
	val appToken: String,
	val oauth: String
)

/// A Slack app ember made that no connect has taken yet, as its maker sees it (never its secrets or tokens).
@Serializable
data class MadeSlackApp (
	val appId: String,
	val name: String,
	val teamId: String,
	/// The Slack workspace's name, when its configuration token says.
	val team: String? = null,
	val created: Long,
	val links: SlackAppLinks,
	/// The link that installs it through Slack's OAuth (a station in ember cloud); none when its tokens are copied by hand.
	val install: String? = null,
	/// Its install's state, what a connect names it by.
	val state: String? = null,
	val installed: Boolean,
	val installedTeam: String? = null
)

@Serializable
data class MeshStatus (
	/// off | missing | running | restarting
	val state: String,
	val origin: String? = null,
	val station: String? = null,
	val workspace: String? = null,
	val workspaceId: String? = null,
	val name: String? = null
)

/// Who is looking: local | access (`email`) | mesh (`email`, `name`, `sub`, `role`, `workspace`, `device`).
@Serializable
data class Viewer (
	val via: String,
	val email: String? = null,
	val name: String? = null,
	val sub: String? = null,
	val role: String? = null,
	val workspace: String? = null,
	val device: String? = null
)

@Serializable
data class SlackTeam (
	val teamId: String,
	val name: String,
	val owner: ConfigTokenOwner? = null
)

@Serializable
data class PendingLogin (
	val id: String,
	val runtime: RuntimeKind,
	val job: LoginJob? = null,
	val created: String? = null,
	/// Why a sign-in that succeeded made no profile.
	val error: String? = null
)

/// A piece of software on a station and whether a newer one is out (updates.rs): the station itself (`station`) or a
/// runtime (`claude`, `codex`).
@Serializable
data class SoftwareVersion (
	/// station | claude | codex
	val id: String,
	val name: String,
	/// On the machine (a runtime may not be: then `updatable` says it can be installed from here).
	val installed: Boolean,
	/// What runs now; none when it is not installed, or not a release (a clone).
	val version: String? = null,
	/// The latest out, when it could be read.
	val latest: String? = null,
	/// The latest is newer than what runs.
	val newer: Boolean,
	/// The pages can update it (or install it, when it is not installed).
	val updatable: Boolean,
	/// Why it cannot be updated from here (the desktop app's station, a runtime installed another way…).
	val note: String? = null,
	/// idle | updating | failed
	val state: String,
	/// What the last update that failed said.
	val message: String? = null,
	/// When what is out was last read.
	val checkedAt: Long? = null
)

/// A station's overview, with what the clients show of its connects and profiles.
@Serializable
data class Overview (
	val viewer: Viewer,
	val connects: List<Connect>,
	val profiles: List<Profile>,
	val processes: List<AgentProcess>,
	val counts: Counts,
	val mesh: MeshStatus? = null,
	val slackUsers: List<String>,
	val slackTeams: List<SlackTeam>,
	val slackApps: List<MadeSlackApp>? = null,
	val disk: DiskRoom? = null,
	val logins: List<PendingLogin>,
	/// This machine's own logins (none from a station older than them).
	val machineLogins: List<MachineLogin>? = null,
	/// The station's and its runtimes' versions, and whether newer ones are out (none from a station older than them).
	val updates: List<SoftwareVersion>? = null,
	/// Its agents' processes, in a line.
	val processesText: String
)

@Serializable
data class RuntimeModels (
	val runtime: RuntimeKind,
	val models: List<String>
)

/// A session with its threads and turns (`session` topic).
@Serializable
data class SessionDetail (
	val session: Session,
	val threads: List<ChatThread>,
	val turns: List<TurnRecord>
)

@Serializable
data class StationView (
	val station: String,
	val id: String,
	val name: String,
	/// Its line in a list: offline since when, or what it is and whether its agents work.
	val summary: String,
	val online: Boolean,
	/// Seconds, from ember cloud.
	val lastSeen: Long? = null,
	val version: String? = null,
	val link: Link,
	val runtimes: List<RuntimeModels>,
	val models: List<ModelOption>,
	val overview: Overview? = null,
	val host: Host? = null,
	/// Its times in words, by field (`createdAt`, `lastActiveAt`, …).
	val time: Map<String, Stamp>? = null
)

/// One thing waited on: what (`text`), how long or how much (`detail`), and whether it is slow | trouble.
@Serializable
data class StatusItem (
	val state: String,
	val text: String,
	val detail: String
)

/// What the core is waiting on (the `status` topic), when it is worth saying: `state` slow (something has taken a
/// while) | trouble (a connection down), absent while all goes as it should; `text` says it in one line.
@Serializable
data class StatusView (
	val state: String? = null,
	val text: String? = null,
	val items: List<StatusItem>
)

